from functools import wraps

def retry_with_backoff(max_retries=3, base_delay=0.5, factor=2):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            delay = base_delay
            last_exc = None
            for attempt in range(max_retries + 1):
                try:
                    return func(*args, **kwargs)
                except (ConnectionResetError, TimeoutError) as e:
                    last_exc = e
                    if attempt == max_retries:
                        break
                    time.sleep(delay)
                    delay *= factor
            raise last_exc
        return wrapper
    return decorator

