export interface CurrentWeather {
  temperatureC: number;
  humidity: number;
  windSpeedKph: number;
  condition: Condition;
}

export interface ForecastDay {
  date: string;
  tempHighC: number;
  tempLowC: number;
  condition: string;
}

export interface Forecast {
  city: string;
  days: ForecastDay[];
}

export class ApiError extends Error {
  constructor(public status: number, message: string) {
    super(message);
    this.name = 'ApiError';
  }
}

interface CacheEntry<T> {
  data: T;
  expiresAt: number;
}

class TtlCache {
  private store = new Map<string, CacheEntry<unknown>>();
  constructor(private ttlMs: number) {}
  get(key: string): unknown | undefined {
    const entry = this.store.get(key);
    if (!entry) return undefined;
    if (Date.now() > entry.expiresAt) {
      this.store.delete(key);
      return undefined;
    }
    return entry.data;
  }
  set(key: string, value: unknown): void {
    this.store.set(key, { data: value, expiresAt: Date.now() + this.ttlMs });
  }
}

export class WeatherClient {
  private cache = new TtlCache(10 * 60 * 1000);
  constructor(private baseUrl: string = 'https://api.weather.example.com') {}

  async getCurrent(city: string): Promise<CurrentWeather> {
    const cacheKey = `current:${city}`;
    const cached = this.cache.get(cacheKey);
    if (cached) return cached as CurrentWeather;
    const data = await this.request<CurrentWeather>(`/v1/current?city=${encodeURIComponent(city)}`);
    this.cache.set(cacheKey, data);
    return data;
  }

  async getForecast(city: string, days: number): Promise<Forecast> {
    const cacheKey = `forecast:${city}:${days}`;
    const cached = this.cache.get(cacheKey);
    if (cached) return cached as Forecast;
    const data = await this.request<Forecast>(`/v1/forecast?city=${encodeURIComponent(city)}&days=${days}`);
    this.cache.set(cacheKey, data);
    return data;
  }

  private async request<T>(path: string): Promise<T> {
    const response = await fetch(`${this.baseUrl}${path}`);
    if (!response.ok) {
      const errorBody = await response.text();
      throw new ApiError(response.status, errorBody || `Request failed with status ${response.status}`);
    }
    return response.json() as Promise<T>;
  }
}
"}

