{"file_path": "file_stats_core.py", "content": "import sys
from collections import Counter

def compute_stats(data):
    text = data.decode('utf-8', errors='replace') if isinstance(data, bytes) else data
    bytes_count = len(data) if isinstance(data, bytes) else len(text.encode('utf-8'))
    lines = text.splitlines()
    line_count = len(lines)
    word_count = len(text.split())
    char_count = len(text)
    return {'bytes': bytes_count, 'lines': line_count, 'words': word_count, 'chars': char_count}

def main(args):
    try:
        if args.file:
            with open(args.file, 'rb') as f:
                data = f.read()
            source = args.file
        else:
            data = sys.stdin.buffer.read()
            source = ''
        stats = compute_stats(data)
        keys = ['bytes', 'lines', 'words', 'chars']
        selected = [k for k in keys if getattr(args, k)]
        if not selected:
            selected = keys
        output = []
        for k in selected:
            output.append(f'{stats[k]} {source}'.strip())  # strip trailing space for stdin
        print('\n'.join(output))
    except FileNotFoundError as e:
        print(f'Error: file not found: {e.filename}', file=sys.stderr)
        sys.exit(1)
    except PermissionError:
        print(f'Error: permission denied for file: {args.file}', file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f'Unexpected error: {e}', file=sys.stderr)
        sys.exit(1)
"}

{"path": "/scripts/validate_sales.py", "content": "import csv
import sys

REQUIRED_COLS = ['transaction_id', 'customer_id', 'product_id', 'quantity', 'price', 'transaction_date']

def validate_row(row, row_num):
    errors = []
    # Check required columns
    for col in REQUIRED_COLS:
        if col not in row:
            errors.append(f"Row {row_num}: missing column '{col}'")
    if errors:
        return errors
    # Check quantity
    try:
        qty = int(row['quantity'])
        if qty < 1:
            errors.append(f"Row {row_num}: quantity is {qty}, must be >= 1")
    except ValueError:
        errors.append(f"Row {row_num}: quantity '{row['quantity']}' is not an integer")
    # Check price
    try:
        price = float(row['price'])
        if price <= 0:
            errors.append(f"Row {row_num}: price is {price}, must be > 0")
    except ValueError:
        errors.append(f"Row {row_num}: price '{row['price']}' is not a float")
    # Check date format (basic)
    date_str = row['transaction_date']
    if not (len(date_str) == 10 and date_str[4] == '-' and date_str[7] == '-"):
        errors.append(f"Row {row_num}: transaction_date '{date_str}' is not in YYYY-MM-DD format")
    return errors

def main():
    if len(sys.argv) != 2:
        print('Usage: python validate_sales.py <csv_path>')
        sys.exit(2)
    csv_path = sys.argv[1]
    violations = []
    with open(csv_path, 'r') as f:
        reader = csv.DictReader(f)
        for row_num, row in enumerate(reader, start=2):  # start at 2 to account for header
            errors = validate_row(row, row_num)
            if errors:
                violations.extend(errors)
    if violations:
        for v in violations:
            print(v)
        sys.exit(1)
    else:
        print('All rows are valid.')
        sys.exit(0)

if __name__ == '__main__':
    main()
"}

